diff --git a/repro/check.js b/repro/check.js
new file mode 100644
index 000000000..baf26f4f2
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,21 @@
+// Exits non-zero while the bug is present: asserts the type of `Test` printed by the
+// compiler is `{ prop1: "hello"; }` (the report's expected type) for the given file.
+const path = require("path");
+const ts = require(process.env.TS_PATH || path.resolve(__dirname, "../built/local/typescript.js"));
+const file = path.resolve(process.argv[2] || path.join(__dirname, "report.ts"));
+const program = ts.createProgram([file], { strict: true, noEmit: true, types: [], target: ts.ScriptTarget.ES2022 });
+const sf = program.getSourceFile(file);
+const checker = program.getTypeChecker();
+const diags = ts.getPreEmitDiagnostics(program);
+if (diags.length) {
+    console.error("unexpected diagnostics:\n" + ts.formatDiagnostics(diags, { getCanonicalFileName: f => f, getCurrentDirectory: () => process.cwd(), getNewLine: () => "\n" }));
+    process.exit(2);
+}
+let alias;
+ts.forEachChild(sf, n => { if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") alias = n; });
+const type = checker.getTypeAtLocation(alias.name);
+const actual = checker.typeToString(type, undefined, ts.TypeFormatFlags.InTypeAlias | ts.TypeFormatFlags.NoTruncation);
+const expected = '{ prop1: "hello"; }';
+console.log(`ts ${ts.version}\ntype Test = ${actual}\nexpected   ${expected}`);
+if (actual !== expected) { console.error("FAIL: Test is not the expected type"); process.exit(1); }
+console.log("PASS");
diff --git a/repro/report.ts b/repro/report.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/report.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
